import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, ActivatedRoute } from '@angular/router';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-product-detail',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  templateUrl: './product-detail.component.html',
  styleUrl: './product-detail.component.css'
})
export class ProductDetailComponent implements OnInit {

  product = {
    id: 1,
    name: 'The Commuter Backpack',
    brand: 'Backpack Co.',
    price: 129.99,
    originalPrice: 159.99,
    description: 'The Commuter Backpack is designed for the modern professional. It features a sleek, minimalist design with ample storage for your laptop, documents, and other essentials. Made from durable, water-resistant materials, it ensures your belongings stay safe and dry.',
    image: 'https://lh3.googleusercontent.com/aida-public/AB6AXuCrquj6BhSU8OymgoV_wCPBRdhYZFlesOCKle4pnu6i8OER7mr1gs1j_qnSHALvGZZxfmyZQHSorHFwq6f978bcapHoM5EsqpKwnGJ3HAbP-2Uapye009r-2AV186gjdDhiP4_Ju8CstOkqq5_7Il4Mjla9KZyC-UTErRuR3tDgnZK-OaIe1ZhPtxd2H338lDAD66zGyi8MiboSBWKt72f56pj4iTcAaU890TmN1wtlTQ_7RIVz7NHHNAkFQOL5dJxIURPoQLLZqnwq',
    category: 'Featured',
    inStock: true,
    rating: 4.5,
    reviewCount: 128,
    features: [
      'Water-resistant materials',
      'Laptop compartment fits up to 15"',
      'Multiple organization pockets',
      'Ergonomic shoulder straps',
      'Lifetime warranty'
    ]
  };

  searchQuery: string = '';
  quantity: number = 1;
  isLoading: boolean = false;

  constructor(private route: ActivatedRoute) {}

  ngOnInit(): void {
    // Get product ID from route parameters
    this.route.params.subscribe(params => {
      if (params['id']) {
        this.loadProduct(params['id']);
      }
    });
  }

  loadProduct(id: string): void {
    this.isLoading = true;
    // Simulate API call
    setTimeout(() => {
      console.log('Loading product with ID:', id);
      this.isLoading = false;
    }, 500);
  }

  onAddToCart(): void {
    console.log('Adding to cart:', this.product, 'Quantity:', this.quantity);
    // Add to cart logic here
  }

  onAddToWishlist(): void {
    console.log('Adding to wishlist:', this.product);
  }

  onSearch(): void {
    if (this.searchQuery.trim()) {
      console.log('Searching for:', this.searchQuery);
    }
  }

  incrementQuantity(): void {
    this.quantity++;
  }

  decrementQuantity(): void {
    if (this.quantity > 1) {
      this.quantity--;
    }
  }

  onQuantityChange(): void {
    if (this.quantity < 1) {
      this.quantity = 1;
    }
  }

  getDiscountPercentage(): number {
    if (this.product.originalPrice && this.product.price) {
      return Math.round(((this.product.originalPrice - this.product.price) / this.product.originalPrice) * 100);
    }
    return 0;
  }
}
<!-- Product Detail Container - matches parent layout -->
<div class="w-full h-full bg-[#fcf9f8]" style='font-family: "Plus Jakarta Sans", "Noto Sans", sans-serif;'>
    <div class="py-6"> <!-- Modified class: removed container, mx-auto, px-4, sm:px-6, lg:px-8 -->
        <div class=""> <!-- Modified class: removed max-w-7xl, mx-auto -->
            <!-- Breadcrumb -->
            <div class="flex flex-wrap gap-2 mb-6">
                <a class="text-[#99674d] hover:text-[#eb6c28] text-sm font-medium leading-normal transition-colors"
                   href="#" routerLink="/home">{{ product.category }}</a>
                <span class="text-[#99674d] text-sm font-medium leading-normal">/</span>
                <span class="text-[#1b120e] text-sm font-medium leading-normal">{{ product.name }}</span>
            </div>            <!-- Product Detail Section -->
            <div class="grid grid-cols-1 lg:grid-cols-2 gap-6 lg:gap-8">

                <!-- Product Image -->
                <div class="w-full aspect-[4/3] rounded-xl overflow-hidden shadow-sm">
                    <div class="w-full h-full bg-center bg-no-repeat bg-cover"
                         [style.background-image]="'url(' + product.image + ')'">
                    </div>
                </div>

                <!-- Product Information -->
                <div class="flex flex-col justify-start">
                    <h1 class="text-[#1b120e] text-2xl lg:text-3xl font-bold leading-tight tracking-[-0.015em] pb-2">
                        {{ product.name }}
                    </h1>
                    <p class="text-[#99674d] text-base font-medium leading-normal pb-4">
                        By {{ product.brand }}
                    </p>
                    <p class="text-[#99674d] text-base font-normal leading-relaxed pb-6">
                        {{ product.description }}
                    </p>                    <!-- Price Section -->
                    <div class="pb-6">
                        <div class="flex flex-wrap items-center gap-3 mb-2">
                            <span class="text-[#1b120e] text-xl lg:text-2xl font-bold leading-normal">${{ product.price }}</span>
                            <span *ngIf="product.originalPrice"
                                  class="text-[#99674d] text-base lg:text-lg line-through">${{ product.originalPrice }}</span>
                            <span *ngIf="getDiscountPercentage() > 0"
                                  class="bg-[#eb6c28] text-white px-2 py-1 rounded text-xs font-bold">
                                {{ getDiscountPercentage() }}% OFF
                            </span>
                        </div>
                        <div class="flex items-center gap-2 mb-4">
                            <div class="flex text-yellow-400">
                                <span *ngFor="let star of [1,2,3,4,5]"
                                      [class]="star <= product.rating ? 'text-yellow-400' : 'text-gray-300'">★</span>
                            </div>
                            <span class="text-[#99674d] text-sm">({{ product.reviewCount }} reviews)</span>
                        </div>
                    </div>                    <!-- Features List -->
                    <div class="pb-6">
                        <h3 class="text-[#1b120e] font-semibold mb-3">Key Features:</h3>
                        <ul class="space-y-2">
                            <li *ngFor="let feature of product.features"
                                class="flex items-center text-sm text-[#99674d]">
                                <svg class="w-4 h-4 text-[#eb6c28] mr-2 flex-shrink-0" fill="currentColor"
                                     viewBox="0 0 20 20">
                                    <path fill-rule="evenodd"
                                          d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
                                          clip-rule="evenodd"></path>
                                </svg>
                                {{ feature }}
                            </li>
                        </ul>
                    </div>

                    <!-- Quantity Selector -->
                    <div class="pb-6"><label class="block text-[#1b120e] font-semibold mb-2">Quantity:</label>
                        <div class="flex items-center gap-3">
                            <button class="w-10 h-10 rounded-lg border border-[#f3ebe7] flex items-center justify-center text-[#99674d] hover:bg-[#f3ebe7] transition-colors"
                                    (click)="decrementQuantity()" [disabled]="quantity <= 1">
                                <svg class="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                                    <path fill-rule="evenodd"
                                          d="M3 10a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1z"
                                          clip-rule="evenodd"></path>
                                </svg>
                            </button>
                            <input type="number"
                                   [(ngModel)]="quantity"
                                   (change)="onQuantityChange()"
                                   class="w-16 h-10 text-center border border-[#f3ebe7] rounded-lg focus:outline-0 focus:ring-2 focus:ring-[#eb6c28]/50 focus:border-[#eb6c28] text-[#1b120e]"
                                   min="1">
                            <button class="w-10 h-10 rounded-lg border border-[#e0e3e6] flex items-center justify-center text-[#60758a] hover:bg-[#f0f2f5] transition-colors"
                                    (click)="incrementQuantity()">
                                <svg class="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                                    <path fill-rule="evenodd"
                                          d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z"
                                          clip-rule="evenodd"></path>
                                </svg>
                            </button>
                        </div>
                    </div>

                    <!-- Action Buttons -->
                    <div class="flex flex-col sm:flex-row gap-4">
                        <button class="flex-1 flex min-w-[120px] cursor-pointer items-center justify-center overflow-hidden rounded-lg h-12 px-6 bg-[#eb6c28] hover:bg-[#d35400] text-white text-base font-bold leading-normal tracking-[0.015em] transition-all focus:ring-2 focus:ring-[#eb6c28] focus:ring-opacity-50"
                                (click)="onAddToCart()"
                                [disabled]="!product.inStock"
                                [class.opacity-50]="!product.inStock">
                            <svg class="w-5 h-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                                <path d="M3 1a1 1 0 000 2h1.22l.305 1.222a.997.997 0 00.01.042l1.358 5.43-.893.892C3.74 11.846 4.632 14 6.414 14H15a1 1 0 000-2H6.414l1-1H14a1 1 0 00.894-.553l3-6A1 1 0 0017 3H6.28l-.31-1.243A1 1 0 005 1H3zM16 16.5a1.5 1.5 0 11-3 0 1.5 1.5 0 013 0zM6.5 18a1.5 1.5 0 100-3 1.5 1.5 0 000 3z"></path>
                            </svg>
                            <span class="truncate">{{ product.inStock ? 'Add to Cart' : 'Out of Stock' }}</span>
                        </button>
                        <button class="flex-1 flex min-w-[120px] cursor-pointer items-center justify-center overflow-hidden rounded-lg h-12 px-6 border border-[#eb6c28] text-[#eb6c28] hover:bg-[#eb6c28] hover:text-white text-base font-bold leading-normal tracking-[0.015em] transition-all focus:ring-2 focus:ring-[#eb6c28] focus:ring-opacity-50"
                                (click)="onAddToWishlist()">
                            <svg class="w-5 h-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                                <path fill-rule="evenodd"
                                      d="M3.172 5.172a4 4 0 015.656 0L10 6.343l1.172-1.171a4 4 0 115.656 5.656L10 17.657l-6.828-6.829a4 4 0 010-5.656z"
                                      clip-rule="evenodd"></path>
                            </svg>
                            <span class="truncate">Add to Wishlist</span>
                        </button>
                    </div>
                </div>
            </div>

            <!-- Additional Product Information -->
            <div class="mt-8 p-6 bg-[#fcf9f8] rounded-lg shadow-sm border border-[#f3ebe7]">
                <div class="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div class="text-center p-4">
                        <div class="w-12 h-12 mx-auto mb-3 text-[#eb6c28]">
                            <svg fill="currentColor" viewBox="0 0 256 256" xmlns="http://www.w3.org/2000/svg">
                                <path d="M248,128a87.34,87.34,0,0,1-17.6,52.81l-46.21-46.21A32,32,0,0,0,160,112H96a32,32,0,0,0-24.19,22.6L25.6,180.81A87.34,87.34,0,0,1,8,128,88,88,0,1,1,248,128ZM128,32a96,96,0,0,0-96,96,96.68,96.68,0,0,0,14.4,50.4L92.6,132.19A16,16,0,0,1,96,128h64a16,16,0,0,1,3.4,4.19L209.6,178.4A96.68,96.68,0,0,0,224,128,96,96,0,0,0,128,32Z"></path>
                            </svg>
                        </div>
                        <h3 class="font-semibold text-[#1b120e] mb-2">Free Shipping</h3>
                        <p class="text-[#99674d] text-sm">Free shipping on orders over $75</p>
                    </div>
                    <div class="text-center p-4">
                        <div class="w-12 h-12 mx-auto mb-3 text-[#eb6c28]">
                            <svg fill="currentColor" viewBox="0 0 256 256" xmlns="http://www.w3.org/2000/svg">
                                <path d="M128,24A104,104,0,1,0,232,128,104.11,104.11,0,0,0,128,24Zm0,192a88,88,0,1,1,88-88A88.1,88.1,0,0,1,128,216Zm40-68a28,28,0,0,1-28,28H116a8,8,0,0,1,0-16h24a12,12,0,0,0,0-24H116a28,28,0,0,1,0-56h24a8,8,0,0,1,0,16H116a12,12,0,0,0,0,24h24A28,28,0,0,1,168,148Z"></path>
                            </svg>
                        </div>
                        <h3 class="font-semibold text-[#1b120e] mb-2">30-Day Returns</h3>
                        <p class="text-[#99674d] text-sm">Easy returns within 30 days</p>
                    </div>
                    <div class="text-center p-4">
                        <div class="w-12 h-12 mx-auto mb-3 text-[#eb6c28]">
                            <svg fill="currentColor" viewBox="0 0 256 256" xmlns="http://www.w3.org/2000/svg">
                                <path d="M208,40H48A24,24,0,0,0,24,64V192a24,24,0,0,0,24,24H208a24,24,0,0,0,24-24V64A24,24,0,0,0,208,40ZM40,64a8,8,0,0,1,8-8H208a8,8,0,0,1,8,8v80H40ZM208,200H48a8,8,0,0,1-8-8V160H216v32A8,8,0,0,1,208,200Z"></path>
                            </svg>
                        </div>
                        <h3 class="font-semibold text-[#1b120e] mb-2">Secure Payment</h3>
                        <p class="text-[#99674d] text-sm">Your payment information is secure</p>
                    </div>
                </div>
            </div>
        </div>
    </div>
    <!-- Footer was here, now it is part of app.component.html -->
</div>
